Definition pch_tcore (c c1 : pcore) : Prop :=
  pc_state c1 = pc_state c /\ pc_f c1 = pc_f c /\ pc_hlim c1 = pc_hlim c /\ pc_len0 c1 = pc_len0 c
  /\ pc_blim_has c1 = pc_blim_has c /\ 0 <= pc_blim c1 <= pc_blim c /\ 0 <= pc_f c1 < 2^14 /\ 0 <= pc_hlim c1 < 2^31.

Lemma pch_fcore_tcore : forall c c1 n, pch_fcore c c1 n -> pch_tcore c c1.
Proof. intros c c1 n (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12). unfold pch_tcore. tauto. Qed.

Definition pch_tail_stmt : Prop :=
  forall rax ra sp gp tp t0x t1x t2 a0 a2 a3 a4 a5 a6 a7
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pv size eol start : Z) (g : bool) (j8 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs pv
          [CB 8 j8; C8 (wz start); C8 (wz eol)] [C8 (wz 0); C8 (wz 0); C8 (wz 0)] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_tcore c c1 ->
  p0 + 2 <= eol <= p0 + Z.of_nat (length bs) -> 0 <= size < 2^64 -> 0 <= start < 2^64 -> 0 <= pv < 2^64 ->
  evt asegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp t0x t1x t2 (wz E) (wz (P + 56)) a0 (wz pv) a2 a3 a4 a5 a6 a7
              (wz P) (wz IN) (wz (P + 76)) (wz (E + 16)) (shw (E + 16)) (wz size) (shw (P + 76)) (wz 2147450880) (shw (P + 56)) (shw IN) t3 t4 t5 t6)
        F (Z_to_bv 64 0xcf478) fc None m1 (seg_rom asegs)).

